#!/usr/bin/env sh

antlr4() {
    java -Xmx500M -cp "../../../scripts/antlr-4.13.2-complete.jar:$CLASSPATH" org.antlr.v4.Tool "$@"
}
rm -fr generated
antlr4 -Dlanguage=Go -package planparserv2 -o generated -no-listener -visitor Plan.g4

# The lexer and parser handleInternal runs are generated by galop
# (https://github.com/martianoff/galop) next to ANTLR's code: PlanGalopLexer and
# PlanGalopParser build ANTLR's contexts and report ANTLR's errors, so the
# visitor and the error listener work unchanged. Download a release binary and
# put it on PATH as `galop`.
if ! command -v galop >/dev/null 2>&1; then
    echo "Error: galop not found. Download it from https://github.com/martianoff/galop/releases." >&2
    exit 1
fi
galop -Dlanguage=Go -Dflavor=antlr -package planparserv2 -visitor -no-listener -Xexact-output-dir -o generated Plan.g4
